OUT=Path('Documents/Student-Guides/Book-Return')
V='LIBRARY-FULLSTACK-V1'
T={
'T46':('Student 46','Create Book Return','46','POST /rest/returns','CreateBookReturnService','CreateBookReturnServiceImpl','Book Return Created Successfully','Update Book Return UI','null Create request','duplicate RET-0001'),
'T47':('Student 47','Read Book Return','47','GET /rest/returns/{id}','ReadBookReturnService','ReadBookReturnServiceImpl','Book Return Read Successfully','Void Book Return UI','ID 999','RET-0002 exists but is VOID'),
'T48':('Student 48','Update Book Return','48','PUT /rest/returns/{id}','UpdateBookReturnService','UpdateBookReturnServiceImpl','Book Return Updated Successfully','Search Book Return UI','null Update request','ID 3 RET-0003 attempts to use RET-0001 owned by ID 1'),
'T49':('Student 49','Void Book Return','49','DELETE /rest/returns/{id}','DeleteBookReturnService','DeleteBookReturnServiceImpl','Book Return Voided Successfully','Create Book Return UI','ID 999','RET-0001 has non-VOID Fine FINE-0001; RET-0003 has no Fine'),
'T50':('Student 50','Search Book Return','50','GET /rest/returns/search?text={text}','SearchBookReturnService','SearchBookReturnServiceImpl','Book Return Search Completed Successfully','Book Return List / Search Results UI','null search text','ret-0001 must find RET-0001 while VOID RET-0002 is excluded')}
M={'T46':'BookReturnResponseDto createBookReturn(BookReturnCreateRequestDto request)','T47':'BookReturnResponseDto readBookReturn(Long id)','T48':'BookReturnResponseDto updateBookReturn(Long id, BookReturnUpdateRequestDto request)','T49':'BookReturnResponseDto deleteBookReturn(Long id)','T50':'List<BookReturnResponseDto> searchBookReturn(String text)'}

def shade(c,f):
 p=c._tc.get_or_add_tcPr();x=OxmlElement('w:shd');x.set(qn('w:fill'),f);p.append(x)
def setup(d):
 for s in d.sections:s.top_margin=Inches(.55);s.bottom_margin=Inches(.55);s.left_margin=Inches(.72);s.right_margin=Inches(.72)
 d.styles['Normal'].font.name='Aptos';d.styles['Normal'].font.size=Pt(10)
 for n,z in [('Title',21),('Heading 1',15),('Heading 2',12.7)]:d.styles[n].font.name='Aptos';d.styles[n].font.size=Pt(z)
def title(d,a,b):
 p=d.add_paragraph(style='Title');p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run(a);p=d.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;r=p.add_run(b);r.bold=True
def table(d,rows,h=('Item','Meaning / Value')):
 t=d.add_table(rows=1,cols=2);t.style='Table Grid';t.cell(0,0).text=h[0];t.cell(0,1).text=h[1];shade(t.cell(0,0),'D9EAF7');shade(t.cell(0,1),'D9EAF7')
 for a,b in rows:c=t.add_row().cells;c[0].text=str(a);c[1].text=str(b)
def code(d,s):
 p=d.add_paragraph();p.paragraph_format.left_indent=Inches(.12);r=p.add_run(textwrap.dedent(s).strip());r.font.name='Consolas';r.font.size=Pt(8);x=OxmlElement('w:shd');x.set(qn('w:fill'),'F3F4F6');p._p.get_or_add_pPr().append(x)
def note(d,s):
 t=d.add_table(rows=1,cols=1);t.style='Table Grid';shade(t.cell(0,0),'FFF7D6');t.cell(0,0).text='Important: '+s
def bullets(d,xs):
 for x in xs:d.add_paragraph(x,style='List Bullet')

def normal(k):
 if k=='T46':return '''@Autowired private BookReturnDao bookReturnDao;\n@Autowired private BookReturnDtoDoMapper mapper;\n@Override public BookReturnResponseDto createBookReturn(BookReturnCreateRequestDto request) {\n BookReturnDO value=mapper.toDO(request);\n return mapper.toResponse(bookReturnDao.save(value));\n}'''
 if k=='T47':return '''@Autowired private BookReturnDao bookReturnDao;\n@Autowired private BookReturnDtoDoMapper mapper;\n@Override public BookReturnResponseDto readBookReturn(Long id) {\n BookReturnDO value=bookReturnDao.findById(id).orElse(null);\n return mapper.toResponse(value);\n}'''
 if k=='T48':return '''@Autowired private BookReturnDao bookReturnDao;\n@Autowired private BookReturnDtoDoMapper mapper;\n@Override public BookReturnResponseDto updateBookReturn(Long id, BookReturnUpdateRequestDto request) {\n BookReturnDO value=bookReturnDao.findById(id).orElse(null);\n mapper.applyUpdate(request,value);\n return mapper.toResponse(bookReturnDao.save(value));\n}'''
 if k=='T49':return '''@Autowired private BookReturnDao bookReturnDao;\n@Autowired private BookReturnDtoDoMapper mapper;\n@Override public BookReturnResponseDto deleteBookReturn(Long id) {\n BookReturnDO value=bookReturnDao.findById(id).orElse(null);\n value.setStatus("VOID");\n return mapper.toResponse(bookReturnDao.save(value));\n}'''
 return '''@Autowired private BookReturnDao bookReturnDao;\n@Autowired private BookReturnDtoDoMapper mapper;\n@Override public List<BookReturnResponseDto> searchBookReturn(String text) {\n String q=text.trim();\n return bookReturnDao.search(q).stream().map(mapper::toResponse).toList();\n}'''
def corrected(k):
 if k=='T46':return '''if(request==null) throw new IllegalArgumentException("Book Return request is required");\nString n=request.getReturnNumber().trim();\nbookReturnDao.findByNormalizedBusinessKey(n).ifPresent(x->{throw new IllegalStateException("Return number already exists");});\nrequest.setReturnNumber(n);\nreturn mapper.toResponse(bookReturnDao.save(mapper.toDO(request)));'''
 if k=='T47':return '''if(id==null) throw new IllegalArgumentException("Book Return ID is required");\nBookReturnDO value=bookReturnDao.findCurrentById(id).orElseThrow(()->new IllegalArgumentException("Book Return not found"));\nreturn mapper.toResponse(value);'''
 if k=='T48':return '''if(id==null||request==null) throw new IllegalArgumentException("Book Return ID and request are required");\nBookReturnDO value=bookReturnDao.findCurrentById(id).orElseThrow(()->new IllegalArgumentException("Book Return not found"));\nString n=request.getReturnNumber().trim();\nbookReturnDao.findByNormalizedBusinessKey(n).filter(x->!x.getBookReturnId().equals(id)).ifPresent(x->{throw new IllegalStateException("Return number already exists");});\nmapper.applyUpdate(request,value);\nreturn mapper.toResponse(bookReturnDao.save(value));'''
 if k=='T49':return '''if(id==null) throw new IllegalArgumentException("Book Return ID is required");\nBookReturnDO value=bookReturnDao.findCurrentById(id).orElseThrow(()->new IllegalArgumentException("Book Return not found"));\nif(bookReturnDao.countDependencies(id)>0) throw new IllegalStateException("Book Return has an active Fine");\nvalue.setStatus("VOID");\nreturn mapper.toResponse(bookReturnDao.save(value));'''
 return '''if(text==null) throw new IllegalArgumentException("Search text is required");\nString q=text.trim();\nif(q.isBlank()) throw new IllegalArgumentException("Search text is required");\nreturn bookReturnDao.searchIgnoreCaseCurrent(q).stream().map(mapper::toResponse).toList();'''
def observation(k):
 return {'T46':'service.createBookReturn(null);','T47':'when(bookReturnDao.findById(999L)).thenReturn(Optional.empty());\nservice.readBookReturn(999L);','T48':'when(bookReturnDao.findById(3L)).thenReturn(Optional.of(existing));\nservice.updateBookReturn(3L,null);','T49':'when(bookReturnDao.findById(999L)).thenReturn(Optional.empty());\nservice.deleteBookReturn(999L);','T50':'service.searchBookReturn(null);'}[k]
def itest(k):
 return {'T46':'assertThrows(IllegalStateException.class,()->service.createBookReturn(request("RET-0001",1L,LocalDate.of(2026,8,16),"COMPLETED")));','T47':'assertEquals("RET-0001",service.readBookReturn(1L).getReturnNumber());\nassertThrows(IllegalArgumentException.class,()->service.readBookReturn(2L));','T48':'assertThrows(IllegalStateException.class,()->service.updateBookReturn(3L,request("RET-0001",5L,LocalDate.of(2026,8,16),"COMPLETED")));','T49':'assertEquals("VOID",service.deleteBookReturn(3L).getStatus());\nassertThrows(IllegalStateException.class,()->service.deleteBookReturn(1L));','T50':'assertTrue(service.searchBookReturn("ret-0001").stream().anyMatch(r->"RET-0001".equals(r.getReturnNumber())));\nassertTrue(service.searchBookReturn("ret-0002").isEmpty());'}[k]
def codes(k,msg):
 x=[('00',msg)]
 if k=='T46':x += [('01','Invalid / missing Book Return request'),('03','Return number already exists')]
 elif k=='T47':x += [('01','Book Return ID is required'),('02','Book Return not found / VOID record not exposed')]
 elif k=='T48':x += [('01','Invalid Book Return ID/request'),('02','Book Return not found'),('03','Return number belongs to another Return')]
 elif k=='T49':x += [('01','Book Return ID is required'),('02','Book Return not found'),('05','Book Return has a non-VOID Fine dependency')]
 else:x += [('01','Search text is required or blank')]
 return x

def initial(k,v):
 st,op,sc,ep,svc,impl,msg,ui,unit,it=v;d=Document();setup(d);title(d,f'{k} - {op} - Initial API Contract',f'{st} | {V} | Book Return Module');d.add_heading('1. Fixed Assignment',1);table(d,[('Track',k),('Student',st),('Operation',op),('Service Code',sc),('Endpoint',ep),('Service Interface',svc),('Method',M[k]),('Success responseCode','00'),('Success Message',msg)]);d.add_heading('2. Frozen JSON Envelope',1);code(d,f'{{\n "serviceCode":"{sc}",\n "responseCode":"00",\n "message":"{msg}",\n "data":{{}}\n}}');d.add_heading('3. Fields',1);table(d,[('bookReturnId','Database ID; response only'),('returnNumber','Business key'),('bookIssueId','Related Book Issue'),('returnDate','Return date'),('status','COMPLETED or VOID')]);d.add_heading('4. Training Data',1);table(d,[('RET-0001','COMPLETED; FINE-0001 OUTSTANDING'),('RET-0002','VOID; related Fine is VOID'),('RET-0003','COMPLETED; no Fine')]);d.add_heading('5. Ownership',1);table(d,[('Presenter','REST Controller, DTO/DO, Mapper, DAO, Flyway, JSON envelope, Thymeleaf'),('Student',impl+', tests and '+ui)]);note(d,'Delete means Void; the row remains with status VOID.');return d

def progressive(k,v):
 st,op,sc,ep,svc,impl,msg,ui,unit,it=v;d=Document();setup(d);title(d,f'{st} - {op} Progressive Testing Guide',f'{k} | Book Return Module | {V}');d.add_paragraph('Follow the approved progression: empty service, focused invocation, normal path, positive Unit Test, realistic next condition, observation, correction, JaCoCo, local PostgreSQL, complete Integration Test, PostgreSQL Testcontainers, frontend STUB/support and partner integration.');d.add_heading('1. Assignment and Flow',1);table(d,[('Backend',op),('Service',svc),('Implementation',impl),('Endpoint',ep),('Service Code',sc),('Frontend',ui),('REST Controller','Presenter-owned')]);table(d,[('Browser','HTTP request'),('Spring Web + Jackson','Request DTO'),('REST Controller','Calls Service'),('Service','Student business logic'),('Mapper','DTO <-> DO'),('DAO','JPA'),('PostgreSQL','Return/Fine state')]);note(d,'The service receives Java DTO values, not raw JSON.');d.add_heading('2. Empty Service and Invocation',1);ret='return java.util.Collections.emptyList();' if k=='T50' else 'return null;';code(d,f'@Service\npublic class {impl} implements {svc} {{\n @Override public {M[k]} {{ {ret} }}\n}}');code(d,f'@ExtendWith(MockitoExtension.class)\nclass {impl}Test {{\n @InjectMocks private {impl} service;\n @Test void shouldInvokeService() {{ /* invoke assigned method */ }}\n}}');d.add_paragraph('Run only this test from Eclipse. Mockito removes the need for the real DAO during Unit Testing.');d.add_heading('3. Natural Successful Path',1);code(d,normal(k));d.add_paragraph('Add a positive Mockito test and keep it as a regression test.');d.add_heading('4. Next Realistic Condition',1);d.add_paragraph(unit+' Do not change the service before running the test.');code(d,observation(k));d.add_paragraph('Read the exception type and first application stack-trace line. NullPointerException means a null reference was used as an object; model the application condition before dereferencing it.');d.add_heading('5. Improved Service',1);code(d,corrected(k));d.add_paragraph('Rerun the new test and the original positive test.');d.add_heading('6. JaCoCo',1);code(d,'mvnw.cmd clean test');table(d,[('Green','Executed'),('Yellow','Partly covered'),('Red','Not executed; room for uncertainty')]);d.add_heading('7. Integration Testing',1);d.add_paragraph('Mockito cannot prove Flyway data, VOID filtering, PostgreSQL comparison, JPA mapping, or Return-to-Fine dependencies.');table(d,[('Unit Test','Service + mocks'),('Local Integration','Spring + Mapper + DAO + PostgreSQL'),('Testcontainers','Same path + temporary PostgreSQL 18')]);d.add_heading('8. JDBC Driver',1);code(d,'spring.datasource.url=jdbc:postgresql://localhost:5432/library_full_stack\nspring.datasource.username=postgres\nspring.datasource.password=postgres\nspring.datasource.driver-class-name=org.postgresql.Driver');code(d,'<dependency>\n <groupId>org.postgresql</groupId>\n <artifactId>postgresql</artifactId>\n <scope>runtime</scope>\n</dependency>\n\n<!-- MySQL learning reference only\n<dependency>\n <groupId>com.mysql</groupId>\n <artifactId>mysql-connector-j</artifactId>\n <scope>runtime</scope>\n</dependency>\n-->\n# MySQL driver: com.mysql.cj.jdbc.Driver');d.add_heading('9. DBeaver',1);code(d,'SELECT book_return_id,return_number,fk_book_issue,return_date,status FROM tbl_book_return ORDER BY book_return_id;\nSELECT fine_id,fine_number,fk_book_return,outstanding_amount,status FROM tbl_fine ORDER BY fine_id;');d.add_paragraph(it);d.add_heading('10. Complete Local Integration Test',1);code(d,'@SpringBootTest\nclass BookReturnLocalIntegrationTest {\n @Autowired '+svc+' service;\n @Test void persistedScenario() {\n  '+itest(k)+'\n }\n}');
 if k=='T50':d.add_heading('10.1 Corrected Search',2);code(d,'@Transactional(readOnly=true)\npublic List<BookReturnDO> searchIgnoreCaseCurrent(String text){\n String p="%"+text.toLowerCase()+"%";\n return entityManager.createQuery("select r from BookReturnDO r where r.status <> \'VOID\' and lower(r.returnNumber) like :p order by r.bookReturnId",BookReturnDO.class).setParameter("p",p).getResultList();\n}')
 d.add_heading('11. PostgreSQL Testcontainers',1);code(d,'@Container\n@ServiceConnection\nstatic PostgreSQLContainer postgres = new PostgreSQLContainer(DockerImageName.parse("postgres:18"));');d.add_paragraph('Add @Testcontainers and repeat the same database cases. Flyway recreates RET-0001, RET-0002, RET-0003 and Fine relationships.');d.add_heading('12. Final Regression',1);code(d,'mvnw.cmd clean test');bullets(d,['Focused test green','Original positive test green','Local PostgreSQL test green','Testcontainers test green','JaCoCo reviewed']);d.add_heading('13. Student-owned Files',1);table(d,[('Service',impl+'.java'),('Tests','Track-specific Unit and Integration tests'),('Frontend',ui),('Presenter-owned','REST Controller, DTO/DO, Mapper, DAO, Flyway, Thymeleaf')]);d.add_heading('14. Frontend Assignment',1);d.add_paragraph('Build a working single-file page first, prove main.js and the button handler, then test against Presenter STUB/support. Refactor only after it works and keep the same /rest URL for partner integration.');code(d,'<script type="module" src="/src/main.js"></script>\nconsole.log("main.js loaded");\ndocument.querySelector("#actionButton").addEventListener("click",()=>console.log("action button reached JavaScript"));');code(d,'if(response.status===404){showMessage("NOT Found");return;}\nif(!response.ok){showMessage("Error Encountered, Please contact Administrator");return;}\nconst body=await response.json();showMessage(body.message);');d.add_paragraph('After the page works, refactor into main.js, bookReturnApi.js, bookReturnForm.js and bookReturnView.js without changing the REST URL.');return d

def updated(k,v):
 st,op,sc,ep,svc,impl,msg,ui,unit,it=v;d=Document();setup(d);title(d,f'{k} - {op} - Updated API Contract',f'{V} | Book Return Module');d.add_heading('1. Fixed Endpoint',1);table(d,[('Track',k),('Service Code',sc),('Endpoint',ep),('Controlled application result','HTTP 200')]);d.add_heading('2. Frozen JSON Envelope',1);code(d,'{\n "serviceCode":"XX",\n "responseCode":"00",\n "message":"...",\n "data":{}\n}');d.add_heading('3. Application Response Codes',1);table(d,codes(k,msg),('responseCode','Meaning'));d.add_heading('4. Frontend Transport Errors',1);table(d,[('HTTP 404','NOT Found'),('Other non-200','Error Encountered, Please contact Administrator')]);note(d,'A valid Search with zero matches returns responseCode 00 and an empty data list.' if k=='T50' else 'Controlled application results use the frozen JSON envelope with HTTP 200.');return d

OUT.mkdir(parents=True,exist_ok=True)
for k,v in T.items():
 f=OUT/f'{k}_{v[1].replace(" ","_")}';f.mkdir(parents=True,exist_ok=True)
 initial(k,v).save(f/f'{k}_01_Initial_API_Contract.docx')
 progressive(k,v).save(f/f'{k}_02_Progressive_Development_Guide.docx')
 updated(k,v).save(f/f'{k}_03_Updated_API_Contract.docx')
print('Generated T46-T50 Book Return student guides')
